<?php
namespace App\Services;
use App\Enums\{CrmInquirySource,OpportunityType};
use App\Models\{Company,CrmPipeline,CrmPipelineStage,Lead,Listing,Opportunity,OpportunityStageHistory,User};
use Illuminate\Auth\Access\AuthorizationException;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class OpportunityService
{
 public function create(User $actor,array $data):Opportunity{$company=$this->company($actor,$data['company_id']??null);$this->authorize($actor,'create',new Opportunity(['company_id'=>$company->id]));return DB::transaction(function()use($actor,$company,$data){$lead=$this->owned(Lead::class,$data['lead_id']??0,$company->id,'lead_id');$listing=isset($data['listing_id'])?$this->owned(Listing::class,$data['listing_id'],$company->id,'listing_id'):null;$pipeline=isset($data['pipeline_id'])?$this->owned(CrmPipeline::class,$data['pipeline_id'],$company->id,'pipeline_id'):app(CrmPipelineProvisioningService::class)->ensureDefault($company);if(!$pipeline->is_active)$this->invalid('pipeline_id',__('crm.errors.pipeline_inactive'));$stage=isset($data['pipeline_stage_id'])?$this->owned(CrmPipelineStage::class,$data['pipeline_stage_id'],$company->id,'pipeline_stage_id'):$pipeline->stages()->where('is_active',true)->orderBy('position')->firstOrFail();if($stage->pipeline_id!==$pipeline->id)$this->invalid('pipeline_stage_id',__('crm.errors.stage_pipeline'));if(!$stage->is_active)$this->invalid('pipeline_stage_id',__('crm.errors.stage_inactive'));$type=OpportunityType::tryFrom($data['type']??$listing?->listing_type?->value??'');if(!$type)$this->invalid('type',__('crm.errors.type_required'));[$budgetMin,$budgetMax]=$this->budget($data['budget_min']??null,$data['budget_max']??null);$owner=$this->owner($company,$data['assigned_to']??$lead->assigned_to);$record=Opportunity::withoutGlobalScopes()->create(['company_id'=>$company->id,'lead_id'=>$lead->id,'listing_id'=>$listing?->id,'pipeline_id'=>$pipeline->id,'pipeline_stage_id'=>$stage->id,'type'=>$type->value,'assigned_to'=>$owner?->id,'budget_min'=>$budgetMin,'budget_max'=>$budgetMax,'currency'=>$this->currency($data['currency']??null),'preferred_property_type'=>$data['preferred_property_type']??null,'preferred_location'=>$data['preferred_location']??null,'preferred_bedrooms'=>$data['preferred_bedrooms']??null,'expected_close_date'=>$data['expected_close_date']??null,'notes'=>$data['notes']??null,'source'=>$data['source']??CrmInquirySource::Manual->value,'source_reference'=>$data['source_reference']??null,'created_by'=>$actor->id,'updated_by'=>$actor->id]);OpportunityStageHistory::withoutGlobalScopes()->create(['company_id'=>$company->id,'opportunity_id'=>$record->id,'to_stage_id'=>$stage->id,'changed_by'=>$actor->id,'changed_at'=>now(),'metadata'=>['event'=>'created']]);return$record->refresh();});}
 public function update(User $actor,Opportunity $record,array $data):Opportunity{$this->authorize($actor,'update',$record);$company=$this->recordCompany($actor,$record);return DB::transaction(function()use($actor,$record,$company,$data){$locked=Opportunity::withoutGlobalScopes()->lockForUpdate()->findOrFail($record->id);foreach(['pipeline_id','pipeline_stage_id'] as $field){if(isset($data[$field])&&(int)$data[$field]!== (int)$locked->{$field})$this->invalid($field,__('crm.errors.stage_via_workflow'));}$listing=isset($data['listing_id'])?$this->owned(Listing::class,$data['listing_id'],$company->id,'listing_id'):null;$owner=$this->owner($company,$data['assigned_to']??$locked->assigned_to);$type=OpportunityType::tryFrom($data['type']??$locked->type->value);if(!$type)$this->invalid('type',__('crm.errors.type_required'));[$budgetMin,$budgetMax]=$this->budget($data['budget_min']??$locked->budget_min,$data['budget_max']??$locked->budget_max);$locked->update(['listing_id'=>$listing?->id,'type'=>$type->value,'assigned_to'=>$owner?->id,'budget_min'=>$budgetMin,'budget_max'=>$budgetMax,'currency'=>$this->currency($data['currency']??$locked->currency),'preferred_property_type'=>$data['preferred_property_type']??$locked->preferred_property_type,'preferred_location'=>$data['preferred_location']??$locked->preferred_location,'preferred_bedrooms'=>$data['preferred_bedrooms']??$locked->preferred_bedrooms,'expected_close_date'=>$data['expected_close_date']??$locked->expected_close_date,'notes'=>$data['notes']??$locked->notes,'updated_by'=>$actor->id]);return$locked->refresh();});}
 public function assign(User $actor,Opportunity $record,?int $userId):Opportunity{$this->authorize($actor,'assign',$record);$company=$this->recordCompany($actor,$record);$owner=$this->owner($company,$userId);$record->update(['assigned_to'=>$owner?->id,'updated_by'=>$actor->id]);return$record->refresh();}
 private function owned(string $class,mixed $id,int $companyId,string $field){$record=$class::withoutGlobalScopes()->findOrFail($id);if((int)$record->company_id!==$companyId)$this->invalid($field,__('crm.errors.cross_company'));return$record;}
 private function owner(Company $company,?int $id):?User{if(!$id)return null;$user=User::withoutGlobalScopes()->findOrFail($id);if((int)$user->company_id!==$company->id)$this->invalid('assigned_to',__('crm.errors.cross_company'));return$user;}
 private function currency(?string $value):?string{if(blank($value))return null;$value=strtoupper(trim($value));if(!preg_match('/^[A-Z]{3}$/',$value))$this->invalid('currency',__('crm.errors.currency'));return$value;}
 private function budget(mixed $min,mixed $max):array{foreach(['budget_min'=>$min,'budget_max'=>$max] as $field=>$value){if($value!==null&&$value!==''&&(!is_numeric($value)||(float)$value<0))$this->invalid($field,__('crm.errors.budget_invalid'));}$min=blank($min)?null:(float)$min;$max=blank($max)?null:(float)$max;if($min!==null&&$max!==null&&$min>$max)$this->invalid('budget_max',__('crm.errors.budget_range'));return[$min,$max];}
 private function company(User $actor,?int $id):Company{if($actor->isSuperAdmin()){if(!$id)$this->invalid('company_id',__('crm.errors.company_required'));return Company::findOrFail($id);}if(!$actor->company_id)$this->invalid('company_id',__('crm.errors.company_required'));if($id&&(int)$id!==(int)$actor->company_id)$this->invalid('company_id',__('crm.errors.cross_company'));return Company::findOrFail($actor->company_id);}
 private function recordCompany(User $actor,Opportunity $r):Company{if(!$actor->isSuperAdmin()&&(int)$actor->company_id!==(int)$r->company_id)throw new AuthorizationException;return Company::findOrFail($r->company_id);}
 private function authorize(User $u,string $a,object $r):void{if(!$u->can($a,$r))throw new AuthorizationException;}
 private function invalid(string $f,string $m):never{throw ValidationException::withMessages([$f=>$m]);}
}
